SELECT e.id, e.raw_request, e.handled_by, e.status, e.outcome, (SELECT count(*) FROM enquiry_events ev WHERE ev.enquiry_id = e.id AND ev.type IN ('clarified','targets_approved') AND ev.undone_at IS NULL)::int, (SELECT count(*) FROM enquiry_agent_runs r WHERE r.enquiry_id = e.id)::int, COALESCE((SELECT sum(r.steps) FROM enquiry_agent_runs r WHERE r.enquiry_id = e.id), 0)::int, COALESCE((SELECT sum(r.input_tokens) FROM enquiry_agent_runs r WHERE r.enquiry_id = e.id), 0)::int, COALESCE((SELECT sum(r.output_tokens) FROM enquiry_agent_runs r WHERE r.enquiry_id = e.id), 0)::int, COALESCE((SELECT sum(r.cost_micros) FROM enquiry_agent_runs r WHERE r.enquiry_id = e.id), 0)::bigint, e.created_at FROM enquiries e ORDER BY e.created_at DESC, e.id LIMIT $1 OFFSET $2
